package dev.tavernagent.mobile.domain

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * GENERATED by scripts/gen_marker_contract.py from testdata/contract/markers.json.
 * Do not edit by hand; run `python scripts/gen_marker_contract.py`.
 */
class CardMarkerContractTest {
    private fun parse(text: String, resolvable: List<String>): List<ContentSegment> =
        CardMarkerParser.parse(text) { key -> if (key in resolvable) "asset:$key" else null }

    private fun images(segs: List<ContentSegment>): List<String> =
        segs.filterIsInstance<ContentSegment.Image>().map { it.rawKey }

    private fun hud(segs: List<ContentSegment>): List<Map<String, String>> =
        segs.filterIsInstance<ContentSegment.Hud>().map { it.values }

    private fun scene(segs: List<ContentSegment>): String =
        segs.filterIsInstance<ContentSegment.Scene>().firstOrNull()?.title ?: ""

    private fun joinedText(segs: List<ContentSegment>): String =
        segs.filterIsInstance<ContentSegment.Text>().joinToString("") { it.content }

    @Test
    fun `img-cmd`() {
        val segs = parse("前 <img cmd=\"smile\"> 后", listOf("smile"))
        assertEquals(listOf("smile"), images(segs))
        assertEquals(emptyList<Map<String, String>>(), hud(segs))
        assertEquals("", scene(segs))
    }

    @Test
    fun `img-eq`() {
        val segs = parse("<img=\"smile\">", listOf("smile"))
        assertEquals(listOf("smile"), images(segs))
        assertEquals(emptyList<Map<String, String>>(), hud(segs))
        assertEquals("", scene(segs))
    }

    @Test
    fun `img-obj`() {
        val segs = parse("<img_obj=\"smile\">", listOf("smile"))
        assertEquals(listOf("smile"), images(segs))
        assertEquals(emptyList<Map<String, String>>(), hud(segs))
        assertEquals("", scene(segs))
    }

    @Test
    fun `img-bg`() {
        val segs = parse("<imgBG=\"smile\">", listOf("smile"))
        assertEquals(listOf("smile"), images(segs))
        assertEquals(emptyList<Map<String, String>>(), hud(segs))
        assertEquals("", scene(segs))
    }

    @Test
    fun `img-src-attr`() {
        val segs = parse("<img src=\"smile\" rel=\"x\">", listOf("smile"))
        assertEquals(listOf("smile"), images(segs))
        assertEquals(emptyList<Map<String, String>>(), hud(segs))
        assertEquals("", scene(segs))
    }

    @Test
    fun `img-bracket`() {
        val segs = parse("[IMG:smile]", listOf("smile"))
        assertEquals(listOf("smile"), images(segs))
        assertEquals(emptyList<Map<String, String>>(), hud(segs))
        assertEquals("", scene(segs))
    }

    @Test
    fun `img-order`() {
        val segs = parse("<img cmd=\"smile\"> 和 [IMG:wave]", listOf("smile", "wave"))
        assertEquals(listOf("smile", "wave"), images(segs))
        assertEquals(emptyList<Map<String, String>>(), hud(segs))
        assertEquals("", scene(segs))
    }

    @Test
    fun `img-unquoted-ignored`() {
        val segs = parse("<img src=smile>", emptyList<String>())
        assertEquals(emptyList<String>(), images(segs))
        assertEquals(emptyList<Map<String, String>>(), hud(segs))
        assertEquals("", scene(segs))
    }

    @Test
    fun `img-escaped-literal`() {
        val segs = parse("[[IMG:smile]", emptyList<String>())
        assertEquals(emptyList<String>(), images(segs))
        assertEquals(emptyList<Map<String, String>>(), hud(segs))
        assertEquals("", scene(segs))
    }

    @Test
    fun `hud`() {
        val segs = parse("[HUD:信任=82/100|好感=40%]", emptyList<String>())
        assertEquals(emptyList<String>(), images(segs))
        assertEquals(listOf(mapOf("信任" to "82/100", "好感" to "40%")), hud(segs))
        assertEquals("", scene(segs))
    }

    @Test
    fun `hud-malformed-kept`() {
        val segs = parse("[HUD:没有等号]", emptyList<String>())
        assertEquals(emptyList<String>(), images(segs))
        assertEquals(emptyList<Map<String, String>>(), hud(segs))
        assertEquals("", scene(segs))
    }

    @Test
    fun `scene`() {
        val segs = parse("[SCENE:雨夜酒馆]", emptyList<String>())
        assertEquals(emptyList<String>(), images(segs))
        assertEquals(emptyList<Map<String, String>>(), hud(segs))
        assertEquals("雨夜酒馆", scene(segs))
    }

    @Test
    fun `var-removed`() {
        val segs = parse("前[VAR:flag=1]后", emptyList<String>())
        assertEquals(emptyList<String>(), images(segs))
        assertEquals(emptyList<Map<String, String>>(), hud(segs))
        assertEquals("", scene(segs))
        assertTrue(joinedText(segs).contains("[VAR:").not())
    }

}
